ValidationRule.errorConditionFormula:
OR ( AND ( RecordTypeId = "01290000000A8Cb", /*Account Review Request*/ OR(ISPICKVAL(Status ,'Not yet assigned - with Account Manager'),ISPICKVAL(Status ,'Assigned to Deal Support')) , OR(CASE(MOD( Due_Date__c - DATE(1900, 1, 7), 7), 0, 0,6, 0,1) = 0, Due_Date__c - TODAY () < 3), NOT ( $Profile.Id = '00e90000001yRGQ' ), /*Qantas Service Profile*/ NOT ( $Profile.Id = '00e90000001yRGN' ), /*Qantas Deal Profile*/ NOT ( $Profile.Id = '00e90000001wK8z' ), /*System Admins Profile*/ NOT ( $Profile.Id = '00e90000001bDil' ), /*QL Qantas Service */ NOT ( $Profile.Id = '00eMo0000064EsA' ), /*QL_Service */ NOT ( $Profile.Name = 'Sales and Distribution-Sales' ) /*Sales and Distribution-Sales */
), AND ( RecordTypeId = "01290000000A8Nt", /*DRA Request*/ OR(ISPICKVAL(Status ,'Open'),ISPICKVAL(Status ,'In Progress')) , OR(CASE(MOD( Due_Date__c - DATE(1900, 1, 7), 7), 0, 0,6, 0,1) = 0, Due_Date__c - TODAY () < 3), NOT ( $Profile.Id = '00e90000001yRGQ' ), /*Qantas Service Profile*/ NOT ( $Profile.Id = '00e90000001yRGN' ), /*Qantas Deal Profile*/ NOT ( $Profile.Id = '00e90000001wK8z' ), /*System Admins Profile*/ NOT ( $Profile.Id = '00e90000001bDil' ), /*QL Qantas Service */ NOT ( $Profile.Id = '00eMo0000064EsA' ), /*QL_Service */ NOT ( $Profile.Name = 'Sales and Distribution-Sales' ) /*Sales and Distribution-Sales */
))
